def _fit_stochastic(
    self,
    X,
    y,
    activations,
    deltas,
    coef_grads,
    intercept_grads,
    layer_units,
    incremental,
):
    params = self.coefs_ + self.intercepts_
    if not incremental or not hasattr(self, "_optimizer"):
        if self.solver == "sgd":
            self._optimizer = SGDOptimizer(
                params,
                self.learning_rate_init,
                self.learning_rate,
                self.momentum,
                self.nesterovs_momentum,
                self.power_t,
            )
        elif self.solver == "adam":
            self._optimizer = AdamOptimizer(
                params,
                self.learning_rate_init,
                self.beta_1,
                self.beta_2,
                self.epsilon,
            )
    if self.early_stopping and incremental:
        raise ValueError("partial_fit does not support early_stopping=True")
    early_stopping = self.early_stopping
    if early_stopping:
        should_stratify = is_classifier(self) and self.n_outputs_ == 1
        stratify = y if should_stratify else None
        X, X_val, y, y_val = train_test_split(
            X,
            y,
            random_state=self._random_state,
            test_size=self.validation_fraction,
            stratify=stratify,
        )
        if is_classifier(self):
            y_val = self._label_binarizer.inverse_transform(y_val)
    else:
        X_val , y_val  = None, None
    n_samples = X.shape[0]
    sample_idx = np.arange(n_samples, dtype=int)
    if self.batch_size == "auto":
        batch_size = min(200, n_samples)
    else:
        if self.batch_size > n_samples:
            warnings.warn(
                "Got `batch_size` less than 1 or larger than "
                "sample size. It is going to be clipped"
            )
        batch_size = np.clip(self.batch_size, 1, n_samples)
    try:
        self.n_iter_ = 0
        for it in range(self.max_iter):
            if self.shuffle:
                sample_idx = shuffle(sample_idx, random_state=self._random_state)
            accumulated_loss = 0.0
            for batch_slice in gen_batches(n_samples, batch_size):
                if self.shuffle:
                    X_batch , y_batch  = _safe_indexing(X, sample_idx[batch_slice]), y[sample_idx[batch_slice]]
                else:
                    X_batch , y_batch  = X[batch_slice], y[batch_slice]
                activations[0] = X_batch
                batch_loss, coef_grads, intercept_grads = self._backprop(
                    X_batch,
                    y_batch,
                    activations,
                    deltas,
                    coef_grads,
                    intercept_grads,
                )
                accumulated_loss += batch_loss * (
                    batch_slice.stop - batch_slice.start
                )
                grads = coef_grads + intercept_grads
                self._optimizer.update_params(params, grads)
            self.n_iter_ += 1
            self.loss_ = accumulated_loss / X.shape[0]
            self.t_ += n_samples
            self.loss_curve_.append(self.loss_)
            if self.verbose:
                print("Iteration %d, loss = %.8f" % (self.n_iter_, self.loss_))
            self._update_no_improvement_count(early_stopping, X_val, y_val)
            self._optimizer.iteration_ends(self.t_)
            if self._no_improvement_count > self.n_iter_no_change:
                if early_stopping:
                    msg = (
                        "Validation score did not improve more than "
                        "tol=%f for %d consecutive epochs."
                        % (self.tol, self.n_iter_no_change)
                    )
                else:
                    msg = (
                        "Training loss did not improve more than tol=%f"
                        " for %d consecutive epochs."
                        % (self.tol, self.n_iter_no_change)
                    )
                is_stopping = self._optimizer.trigger_stopping(msg, self.verbose)
                if is_stopping:
                    break
                else:
                    self._no_improvement_count = 0
            if incremental:
                break
            if self.n_iter_ == self.max_iter:
                warnings.warn(
                    "Stochastic Optimizer: Maximum iterations (%d) "
                    "reached and the optimization hasn't converged yet."
                    % self.max_iter,
                    ConvergenceWarning,
                )
    except KeyboardInterrupt:
        warnings.warn("Training interrupted by user.")
    if early_stopping:
        self.coefs_ , self.intercepts_  = self._best_coefs, self._best_intercepts

