            else:
                newlines = 1
        elif (
            current_line.is_def or current_line.is_decorator
        ) and not self.previous_line.is_def:
            if current_line.depth:
                newlines = min(1, before)
            else:
                newlines = 1
        else:
            newlines = 0
    else:
        newlines = 1 if current_line.depth else 2
    return newlines, 0

