                        K.flat[::n_samples + 1] += current_alpha
                        dual_coef[:] = linalg.solve(K, target, sym_pos=True,
                                                 overwrite_a=False).ravel()
                        K.flat[::n_samples + 1] -= current_alpha
                    if has_sw:
                        dual_coefs *= sw[np.newaxis, :]
                    coef = safe_sparse_dot(dual_coefs, X, dense_output=True).T
                    if ravel:
                        coef = coef.ravel()
                    return coef
            except linalg.LinAlgError:
                solver = 'svd'
        else:
            A , Xy  = safe_sparse_dot(X.T, X, dense_output=True), safe_sparse_dot(X.T, y, dense_output=True)
            if one_alpha:
                A.flat[::n_features + 1] += alpha[0]
                try:
                    coef = linalg.solve(A, Xy, sym_pos=True,
                                        overwrite_a=True).T
                    if ravel:
                        coef = coef.ravel()
                    return coef
                except linalg.LinAlgError:
                    solver = 'svd'
            else:
                coefs = np.empty([n_targets, n_features])
                for coef, target, current_alpha in zip(
                        coefs, Xy.T, alpha):
                    A.flat[::n_features + 1] += current_alpha
                    coef[:] = linalg.solve(A, target, sym_pos=True,
                                           overwrite_a=False).ravel()
                    A.flat[::n_features + 1] -= current_alpha
                return coefs
    if solver == 'svd':
        alpha_dim = alpha.ndim
        if alpha_dim == 1 and len(alpha) != n_targets:
            alpha = alpha[:, np.newaxis]
        alpha = np.atleast_2d(alpha)
        assert alpha.ndim == 2
        U, s, Vt = linalg.svd(X, full_matrices=False)
        idx = s > 1e-15  
        UTy , s[idx == False] = U.T.dot(y), 0.
        d = (s[np.newaxis, :, np.newaxis] /
             (s[np.newaxis, :, np.newaxis] ** 2 + alpha[:, np.newaxis, :]))
        d_UT_y , coef_  = d * UTy[np.newaxis, :, :], np.empty([alpha.shape[0], n_targets, n_features])
        for dUTy, coef_slice in zip(d_UT_y, coef_):
            coef_slice[:] = Vt.T.dot(dUTy).T
        if (not alpha_dim) or (alpha_dim == 1 and alpha.size == n_targets):
            coef_ = coef_.reshape(n_targets, n_features)
            if ravel:
                coef_ = coef_.ravel()
        else:
            if ravel:
                coef_ = coef_.squeeze()
        return coef_

def make_circles(n_samples=100, shuffle=True, noise=None, random_state=None,
        factor=.8):
    if factor > 1 or factor < 0:
        raise ValueError("'factor' has to be between 0 and 1.")
    generator , linspace  = check_random_state(random_state), np.linspace(0, 2 * np.pi, n_samples / 2 + 1)[:-1]
    outer_circ_x = np.cos(linspace)
    outer_circ_y , inner_circ_x , inner_circ_y  = np.sin(linspace), outer_circ_x * factor, outer_circ_x * factor
    X , y  = np.vstack((np.append(outer_circ_x, inner_circ_x), np.append(outer_circ_y, inner_circ_y))).T, np.hstack([np.zeros(n_samples / 2), np.ones(n_samples / 2)])
    if shuffle:
        X, y = util_shuffle(X, y, random_state=generator)
    if not noise is None:
        X += generator.normal(scale=noise, size=X.shape)
    return X, y.astype(np.int)

def roc_curve(y_true, y_score):
    y_true = y_true.ravel()
    classes = np.unique(y_true)
    if classes.shape[0] != 2:
        raise ValueError("ROC is defined for binary classification only")
    y_score = y_score.ravel()
    thresholds = np.sort(np.unique(y_score))[::-1]
    n_pos , n_neg , thresholds  = float(np.sum(y_true == classes[1])), float(np.sum(y_true == classes[0])), np.unique(y_score)  
    neg_value, pos_value = classes[0], classes[1]
    tpr , fpr  = np.empty(thresholds.size), np.empty(thresholds.size)  
    dpos = dneg = sum_pos = sum_neg = idx = 0
    sorted_signal = sorted(zip(y_score, y_true), reverse=True)
    last_input = sorted_signal[0][0]
    for each, value in sorted_signal:
        if each == last_input:
            if value == pos_value:
                dpos += 1
            else:
                dneg += 1
        else:
            tpr[idx] , fpr[idx]  = (sum_pos + dpos) / n_pos, (sum_neg + dneg) / n_neg
            sum_pos += dpos
            sum_neg += dneg
            dpos , dneg  = 1 if value == pos_value else 0, 1 if value == neg_value else 0
            idx += 1
            last_input = each
    else:
        tpr[-1] , fpr[-1]  = (sum_pos + dpos) / n_pos, (sum_neg + dneg) / n_neg
    if fpr.shape[0] == 2:
        fpr , tpr  = np.array([0.0, fpr[0], fpr[1]]), np.array([0.0, tpr[0], tpr[1]])
    elif fpr.shape[0] == 1:
        fpr , tpr  = np.array([0.0, fpr[0], 1.0]), np.array([0.0, tpr[0], 1.0])
    return fpr, tpr, thresholds

